// `make docs`: regenerates the sections of README files that sit below a generated marker.
// A marker names its source: <!-- generated by make docs from features/: do not edit -->. A source ending in
// " --help" is a CLI source file: its help output's "Commands:" block becomes the Commands table.
// The DOCS-GEN check runs the same code without writing and fails on any difference.
import { execFileSync } from "node:child_process";
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { parseFeature } from "@opensoftware/spec-files";

const MARKER = /^<!-- generated by make docs from (\S+?(?: --help)?): do not edit -->$/;
const SKIP_DIRS = new Set([".git", "node_modules", "docs", ".tools", "reports"]);

export interface DocsOptions {
  write: boolean;
  /** Only these README files, relative to the root. */
  only?: string[];
  /** Only README files below this folder, relative to the root. */
  under?: string;
}

export interface StaleSection {
  file: string;
  line: number;
  source: string;
}

/** Writes (or, without `write`, only reports) every generated section that differs from its source. */
export function generateDocs(root: string, options: DocsOptions): number {
  const stale = refreshDocs(root, options);
  for (const section of stale) {
    const verb = options.write ? "updated" : "out of date";
    process.stdout.write(`${section.file}:${section.line} section from ${section.source} ${verb}\n`);
  }
  return options.write || stale.length === 0 ? 0 : 1;
}

export function refreshDocs(root: string, options: DocsOptions): StaleSection[] {
  const stale: StaleSection[] = [];
  const below = options.under ? join(root, options.under) : root;
  const readmes = options.only?.map((file) => join(root, file)) ?? findReadmes(below, root);
  for (const readme of readmes) {
    const before = readFileSync(readme, "utf8");
    const lines = before.split("\n");
    const out: string[] = [];
    for (let index = 0; index < lines.length; index++) {
      const line = lines[index] as string;
      out.push(line);
      const source = MARKER.exec(line)?.[1];
      if (!source) continue;
      let end = index + 1;
      while (end < lines.length && !(lines[end] as string).startsWith("## ")) end++;
      const body = render(dirname(readme), source);
      if (body === undefined) {
        out.push(...lines.slice(index + 1, end));
      } else {
        if (
          lines
            .slice(index + 1, end)
            .join("\n")
            .trim() !== body.trim()
        ) {
          stale.push({ file: relative(root, readme).split("\\").join("/"), line: index + 1, source });
        }
        out.push("", ...body.split("\n"), "");
      }
      index = end - 1;
    }
    const after = out.join("\n").replace(/\n*$/, "\n");
    if (options.write && after !== before) writeFileSync(readme, after);
  }
  return stale;
}

function render(moduleDir: string, source: string): string | undefined {
  if (source === "features/") return scenarioTable(join(moduleDir, "features"));
  if (source.endsWith("config.schema.json")) return configTable(join(moduleDir, source));
  if (source.endsWith(" --help")) return commandTable(moduleDir, source.slice(0, -" --help".length));
  return undefined;
}

function scenarioTable(dir: string): string {
  const rows: string[] = [];
  for (const file of listFiles(dir).filter((name) => name.endsWith(".feature"))) {
    // SPEC reports files that do not parse; they have no scenarios here.
    for (const scenario of parseFeature(file, readFileSync(file, "utf8")).scenarios) {
      const [id = "(no ID)"] = scenario.ids;
      const [status = "(no status)"] = scenario.statuses;
      rows.push(`| ${id} | ${status} | ${scenario.name.replaceAll("|", "\\|")} |`);
    }
  }
  if (rows.length === 0) return "This module has no scenarios yet.";
  return ["| ID | Status | Scenario |", "| --- | --- | --- |", ...rows.sort()].join("\n");
}

function configTable(file: string): string {
  if (!existsSync(file)) return "This module has no configuration.";
  const schema = JSON.parse(readFileSync(file, "utf8")) as {
    properties?: Record<string, { type?: string; default?: unknown; description?: string }>;
  };
  const rows = Object.entries(schema.properties ?? {}).map(
    ([name, property]) =>
      `| \`${name}\` | ${property.type ?? ""} | ${property.default === undefined ? "" : `\`${JSON.stringify(property.default)}\``} | ${property.description ?? ""} |`,
  );
  if (rows.length === 0) return "This module has no configuration.";
  return ["| Variable | Type | Default | Meaning |", "| --- | --- | --- | --- |", ...rows].join("\n");
}

/** The "Commands:" block of `node <cli> --help`: one row per line, usage and meaning split by two spaces. */
function commandTable(moduleDir: string, cli: string): string {
  const help = execFileSync(process.execPath, [cli, "--help"], { cwd: moduleDir, encoding: "utf8" });
  const block = help.split(/^Commands:\n/m)[1] ?? "";
  const rows = block
    .split(/\n\s*\n/)[0]
    ?.split("\n")
    .map((line) => line.trim().split(/\s{2,}/))
    .filter((cells) => cells.length === 2)
    .map((cells) => cells.map((cell) => cell.replaceAll("|", "\\|")))
    .map(([usage, meaning]) => `| \`${usage}\` | ${meaning} |`);
  if (!rows?.length) return "This module has no commands.";
  return ["| Command | What it does |", "| --- | --- |", ...rows].join("\n");
}

function findReadmes(start: string, root: string): string[] {
  const found: string[] = [];
  const visit = (dir: string): void => {
    for (const entry of readdirSync(dir).sort()) {
      if (SKIP_DIRS.has(entry)) continue;
      const full = join(dir, entry);
      if (statSync(full).isDirectory()) visit(full);
      else if (entry === "README.md" && dir !== root) found.push(full);
    }
  };
  visit(start);
  return found;
}

function listFiles(dir: string): string[] {
  if (!existsSync(dir)) return [];
  return readdirSync(dir)
    .sort()
    .flatMap((entry) => {
      const full = join(dir, entry);
      return statSync(full).isDirectory() ? listFiles(full) : [full];
    });
}
